// Normalise the ingest request. `target_path` is the root to index;
// `paths` is an optional explicit subset (skip discovery); `options` carries
// workflow knobs (e.g. {max_chunk_bytes: 24576, force_reindex: true}).
const body = $input.first().json.body || $input.first().json || {};
const target_path = (body.target_path || '').toString().trim();
if (!target_path) {
  throw new Error("'target_path' is required in the webhook body");
}
return [{
  json: {
    target_path,
    workspace_id: body.workspace_id || 'default',
    paths: Array.isArray(body.paths) ? body.paths : [],
    options: body.options || {}
  }
}];

// PRE-CHUNK: file discovery. Emit one item per source file to chunk. When
// the caller passed an explicit `paths` subset, use it verbatim; otherwise a
// real deployment walks `target_path` here (a Read/Move-Binary-Files or
// Execute-Workflow discovery step). Each item carries the absolute path the
// sidecar will read, plus the workspace + options pass-through.
const inp = $input.first().json;
const paths = (inp.paths && inp.paths.length) ? inp.paths : [inp.target_path];
return paths.map(p => ({
  json: {
    path: p,
    workspace_id: inp.workspace_id,
    options: inp.options
  }
}));

// SLICE 3 — attach structural entities to chunks + build the Memgraph
// graph-write payloads. Runs once for all items; each item is paired by index
// with its chunk reply (the Chunk node) and its discovery record. The entity
// reply ($json here) and the chunk reply are produced per file, so index i of
// each node's output is the same file.
//
// Output: ONE item per file carrying
//   * mem_chunks  — chunk records with `entities` attached (line-range match),
//                   used by BOTH the embed branch (Expand Chunks) and the
//                   Memgraph upsert. memgraph.upsert ignores the extra chunk
//                   fields; it reads {id, path, symbol, language, entities}.
//   * calls_pairs / imports_pairs / inherits_pairs — {source,target} edge
//                   lists for memgraph.relate (rel_type CALLS/IMPORTS/INHERITS).
const entItems = $input.all();
const chunkItems = $('Chunk (Tree-sitter Sidecar)').all();
const discoverItems = $('Discover Files').all();
const out = [];
for (let i = 0; i < entItems.length; i++) {
  const ent = entItems[i].json || {};
  const chunkResp = (chunkItems[i] && chunkItems[i].json) || {};
  const disc = (discoverItems[i] && discoverItems[i].json) || {};
  const path = ent.path || chunkResp.path || disc.path;
  const language = ent.language || chunkResp.language || null;
  const module = ent.module || null;
  const workspace_id = disc.workspace_id || 'default';
  const chunks = chunkResp.chunks || [];

  const functions = ent.functions || [];
  const classes = ent.classes || [];
  const imports = ent.imports || [];
  const calls = ent.calls || [];

  // Flat (name, line) list of every entity, so we can assign each to the chunk
  // whose line range covers it. Methods inherit their class's definition line.
  const lineEntities = [];
  for (const f of functions) lineEntities.push({ name: f.name, line: f.line });
  for (const c of classes) {
    lineEntities.push({ name: c.name, line: c.line });
    for (const m of (c.methods || [])) lineEntities.push({ name: m, line: c.line });
  }
  for (const im of imports) lineEntities.push({ name: im.module, line: im.line });
  for (const cl of calls) lineEntities.push({ name: cl.callee, line: cl.line });

  // One mem_chunk per chunk, entities = names whose line falls inside the
  // chunk, plus the file's module identity (anchors IMPORTS + MENTIONS) and
  // the chunk's own symbol. Extra fields (line/byte ranges, kind) ride along
  // for the embed step; memgraph.upsert ignores them.
  const mem_chunks = chunks.map((c, i2) => {
    const names = new Set();
    if (module) names.add(module);
    if (c.symbol_name) names.add(c.symbol_name);
    for (const le of lineEntities) {
      if (le.line >= c.start_line && le.line <= c.end_line && le.name) names.add(le.name);
    }
    return {
      id: `${workspace_id}:${path}:${c.byte_start}`,
      path,
      workspace: workspace_id,
      language,
      symbol: c.symbol_name || null,
      chunk_index: i2,
      start_line: c.start_line,
      end_line: c.end_line,
      byte_start: c.byte_start,
      byte_end: c.byte_end,
      kind: c.kind,
      entities: Array.from(names)
    };
  });

  // Typed Entity->Entity edges for memgraph.relate. CALLS: caller->callee.
  // IMPORTS: this file's module -> imported module. INHERITS: class -> base.
  const calls_pairs = calls
    .filter(c => c.caller && c.callee)
    .map(c => ({ source: c.caller, target: c.callee }));
  const imports_pairs = module
    ? imports.filter(im => im.module).map(im => ({ source: module, target: im.module }))
    : [];
  const inherits_pairs = [];
  for (const c of classes) {
    for (const b of (c.bases || [])) {
      if (c.name && b) inherits_pairs.push({ source: c.name, target: b });
    }
  }

  out.push({ json: {
    path, language, module, workspace_id,
    mem_chunks,
    calls_pairs, imports_pairs, inherits_pairs,
    counts: ent.counts || {}
  }});
}
return out;

// POST-CHUNK: fan each file's entity-attached chunk list out to one item per
// chunk for embed+index. Each chunk already carries its `entities` (Slice 3),
// so the indexed record and the Memgraph nodes agree on the entity set. The
// sidecar returns ranges (not bytes); the downstream step slices the file by
// byte_start/byte_end when it needs the chunk text to embed.
const out = [];
for (const item of $input.all()) {
  const f = item.json;
  const chunks = f.mem_chunks || [];
  if (!chunks.length) {
    out.push({ json: { path: f.path, language: f.language, workspace_id: f.workspace_id, chunk: null, skipped: true } });
    continue;
  }
  for (const c of chunks) {
    out.push({ json: {
      id: c.id,
      workspace_id: f.workspace_id,
      path: f.path,
      language: f.language,
      chunk_index: c.chunk_index,
      start_line: c.start_line,
      end_line: c.end_line,
      byte_start: c.byte_start,
      byte_end: c.byte_end,
      kind: c.kind,
      symbol_name: c.symbol || null,
      entities: c.entities || []
    }});
  }
}
return out;

// Aggregate the per-chunk index results into one ingest summary for the
// webhook response.
const items = $input.all();
const chunks = items.filter(i => !i.json.skipped);
const paths = new Set(items.map(i => i.json.path).filter(Boolean));
return [{
  json: {
    ok: true,
    files_ingested: paths.size,
    chunks_indexed: chunks.length,
    ast_aware: true,
    graph_entities: true
  }
}];
